import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"36、【明夷】 离下坤上","description":"横渠易说 - 36、【明夷】 离下坤上","frontmatter":{"title":"36、【明夷】 离下坤上","description":"横渠易说 - 36、【明夷】 离下坤上"},"headers":[],"relativePath":"zh/classics/hengqu/038.md","filePath":"zh/classics/hengqu/038.md"}'),l={name:"zh/classics/hengqu/038.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_36、【明夷】-离下坤上" tabindex="-1">36、【明夷】 离下坤上 <a class="header-anchor" href="#_36、【明夷】-离下坤上" aria-label="Permalink to “36、【明夷】 离下坤上”">​</a></h1><h3 id="彖曰-明入地中-明夷-内文明而外柔顺-以蒙大难-文王以之。-利艰贞-晦其明也-内难而能正其志-箕子以之。" tabindex="-1">彖曰：明入地中，明夷，内文明而外柔顺，以蒙大难，文王以之。“利艰贞”，晦其明也，内难而能正其志，箕子以之。 <a class="header-anchor" href="#彖曰-明入地中-明夷-内文明而外柔顺-以蒙大难-文王以之。-利艰贞-晦其明也-内难而能正其志-箕子以之。" aria-label="Permalink to “彖曰：明入地中，明夷，内文明而外柔顺，以蒙大难，文王以之。“利艰贞”，晦其明也，内难而能正其志，箕子以之。”">​</a></h3><p>文王体一卦之用，箕子以六五一爻之德，文王难在外，箕子难在内也。</p><h3 id="象曰-明入地中-明夷-君子以莅众用晦而明。" tabindex="-1">象曰：明入地中，明夷，君子以莅众用晦而明。 <a class="header-anchor" href="#象曰-明入地中-明夷-君子以莅众用晦而明。" aria-label="Permalink to “象曰：明入地中，明夷，君子以莅众用晦而明。”">​</a></h3><p>不任察而不失其治也。</p><h3 id="初九-明夷于飞-垂其翼。君子于行-三日不食。有攸往-主人有言。-象曰-君子于行-义不食也。" tabindex="-1">初九，明夷于飞，垂其翼。君子于行，三日不食。有攸往，主人有言。 象曰：“君子于行”，义不食也。 <a class="header-anchor" href="#初九-明夷于飞-垂其翼。君子于行-三日不食。有攸往-主人有言。-象曰-君子于行-义不食也。" aria-label="Permalink to “初九，明夷于飞，垂其翼。君子于行，三日不食。有攸往，主人有言。 象曰：“君子于行”，义不食也。”">​</a></h3><p>进应于上，为三所困，故曰“于飞垂翼”。君子避患当速，势不与抗，退而远行，不遑暇食，静以自守，非有所往之时也。</p><h3 id="六二-明夷-夷于左股。用拯马壮-吉。-象曰-六二之吉-顺以则也。" tabindex="-1">六二，明夷，夷于左股。用拯马壮，吉。 象曰：六二之吉，顺以则也。 <a class="header-anchor" href="#六二-明夷-夷于左股。用拯马壮-吉。-象曰-六二之吉-顺以则也。" aria-label="Permalink to “六二，明夷，夷于左股。用拯马壮，吉。 象曰：六二之吉，顺以则也。”">​</a></h3><p>与三同体，三为六应，故曰“夷于左股”，居中履顺，难不能及，故曰“用拯马壮吉”。马谓初九，亦为己用，故欲拯闇同。</p><h3 id="九三-明夷于南狩-得其大首-不可疾-贞。-象曰-南狩之志-乃大得也。" tabindex="-1">九三，明夷于南狩，得其大首，不可疾，贞。 象曰：南狩之志，乃大得也。 <a class="header-anchor" href="#九三-明夷于南狩-得其大首-不可疾-贞。-象曰-南狩之志-乃大得也。" aria-label="Permalink to “九三，明夷于南狩，得其大首，不可疾，贞。 象曰：南狩之志，乃大得也。”">​</a></h3><p>九三进获明夷之主，故曰“南狩得其大首”。</p><h3 id="六四-入于左腹-获明夷之心-于出门庭。-象曰-入于左腹-获心意也。" tabindex="-1">六四，入于左腹，获明夷之心，于出门庭。 象曰：“入于左腹”，获心意也。 <a class="header-anchor" href="#六四-入于左腹-获明夷之心-于出门庭。-象曰-入于左腹-获心意也。" aria-label="Permalink to “六四，入于左腹，获明夷之心，于出门庭。 象曰：“入于左腹”，获心意也。”">​</a></h3><p>与上六同为一体，故曰“入于左腹”，与五亲比，故曰“出门”“获明夷之心”。盖用柔履中，其志相得，故曰“获心意”也。</p><h3 id="六五-箕子之明夷-利贞。-象曰-箕子之贞-明不可息也。" tabindex="-1">六五，箕子之明夷，利贞。 象曰：箕子之贞，明不可息也。 <a class="header-anchor" href="#六五-箕子之明夷-利贞。-象曰-箕子之贞-明不可息也。" aria-label="Permalink to “六五，箕子之明夷，利贞。 象曰：箕子之贞，明不可息也。”">​</a></h3><p>虽近于闇，然柔顺履中，闇不能掩，箕子之正也。</p><h3 id="上六-不明晦-初登于天-后入于地。-象曰-初登于天-照四国也-后入于地-失则也。" tabindex="-1">上六，不明晦，初登于天，后入于地。 象曰：“初登于天”，照四国也；“后入于地”，失则也。 <a class="header-anchor" href="#上六-不明晦-初登于天-后入于地。-象曰-初登于天-照四国也-后入于地-失则也。" aria-label="Permalink to “上六，不明晦，初登于天，后入于地。 象曰：“初登于天”，照四国也；“后入于地”，失则也。”">​</a></h3>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
